arguments.command:
curl -s -X POST https://slack.com/api/users.list -H 'Content-Type: application/x-www-form-urlencoded' --data 'token=<TOKEN>' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR:', d); sys.exit()
for u in d['members']:
    if 'rivera' in u.get('real_name','').lower() or u.get('real_name','').startswith('Sam'):
        print(u['id'], '|', u.get('real_name'), '|', u.get('profile',{}).get('display_name'))
"

